package com.example.starter.trial.domain;

/**
 * 真实分组（揭盲前对调用方不可见）。
 */
public enum Assignment {
    /** 试验组 */
    TREATMENT,
    /** 对照组 */
    CONTROL
}

package com.example.starter.trial.domain;

/**
 * 受试者状态。
 */
public enum SubjectStatus {
    /** 在组（盲态） */
    ENROLLED,
    /** 已揭盲（终态，不可回退） */
    UNBLINDED
}

package com.example.starter.trial.domain;

/**
 * 揭盲申请状态。
 */
public enum UnblindingStatus {
    /** 仅第一名授权人确认，尚未生效 */
    PENDING,
    /** 两名不同授权人确认完成，揭盲生效（终态） */
    COMPLETED
}

