 * 对“试验+中心”序列行加行锁（须在发号器初始化该行之后、事务内调用），
 * 使同中心并发入组在进入区组分配前串行提交。
 */
public void lockSiteSequence(String trialId, String siteCode) {
    jdbc.queryForObject(
            "SELECT current_no FROM site_random_sequence WHERE trial_id = ? AND site_code = ? FOR UPDATE",
            Long.class, trialId, siteCode);
}

/**
 * 中心内已成功入组（已提交可见）的受试者数，用作下一例的区组位置基数。
 */
public long countSubjectsAtSite(String trialId, String siteCode) {
    Long count = jdbc.queryForObject(
            "SELECT COUNT(1) FROM trial_subject WHERE trial_id = ? AND site_code = ?",
            Long.class, trialId, siteCode);
    return count == null ? 0L : count;
}

